    if (!confirm('确定清除当前项目的 AI 对话记忆？此操作不可恢复。')) return;
    localStorage.removeItem(CHAT_STORAGE_KEY(currentProjectId));
    setMessages([{ role: 'system', content: SYSTEM_PROMPT }]);
  };

  return (
